	const tasks = 500
	wg.Add(tasks)
	for i := 0; i < tasks; i++ {
		go func(id int) {
			defer wg.Done()
			time.Sleep(2 * time.Millisecond)
		}(i)
	}

	wg.Wait()
	close(stopCPU)
	time.Sleep(50 * time.Millisecond)
