package main

import (
	"fmt"
	"net"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

func main() {
	runtime.GOMAXPROCS(2)
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}
	defer ln.Close()

	var connected int64
	var wg sync.WaitGroup

	// Эхо-сервер
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			go func(c net.Conn) {
				defer c.Close()
				buf := make([]byte, 16)
				for {
					n, err := c.Read(buf)
					if err != nil {
						return
					}
					c.Write(buf[:n])
				}
			}(conn)
		}
	}()

	// 500 клиентов
	const clients = 500
	wg.Add(clients)

	for i := 0; i < clients; i++ {
		go func() {
			defer wg.Done()
			c, err := net.Dial("tcp", ln.Addr().String())
			if err != nil {
				return
			}
			defer c.Close()

			atomic.AddInt64(&connected, 1)
			c.Write([]byte("ping"))
			buf := make([]byte, 16)
			c.Read(buf)
			time.Sleep(50 * time.Millisecond)
		}()
	}

	wg.Wait()
	fmt.Printf("Успешно обслужено %d TCP клиентов на %d P\n", atomic.LoadInt64(&connected), runtime.GOMAXPROCS(0))
	fmt.Printf("Итоговое число горутин: %d\n", runtime.NumGoroutine())
}

